using Astrea.RunModifiers;
using Spine.Unity;
using UnityEngine;
using UnityEngine.AddressableAssets;

namespace Astrea;

[CreateAssetMenu(fileName = "DiceClearingReward", menuName = "Data/Rewards/DiceClearingReward", order = 0)]
public class DiceClearingReward : ClearingReward
{
	private static readonly AGLog<DiceClearingReward> Log = new AGLog<DiceClearingReward>();

	[SerializeField]
	[Tooltip("AssetRefFixer will fill this")]
	public AssetReferenceT<SkeletonDataAsset> chestSkeletonDataAssetRef;

	[SerializeField]
	private bool epicDie;

	public SkeletonDataAsset chestSkeletonDataAsset
	{
		get
		{
			Log.Debug($"AnimationData:{this} will load SkeletonDataAsset assetGuid:{chestSkeletonDataAssetRef.AssetGUID}", this);
			return AGSingletonMonoBehaviour<AddressablesAssetReferenceManager>.Instance.LoadFromRef(chestSkeletonDataAssetRef);
		}
		set
		{
		}
	}

	protected override void InitializePropPrefab(GameObject rewardPropGameObject)
	{
		rewardPropGameObject.GetComponent<ChestRewardProp>().InitializeChest(chestSkeletonDataAsset, epicDie);
	}

	protected override Reward[] GetRewards()
	{
		if (ReferenceSingleton<RunModifiersManager>.Instance.DiceShortageRunModifier != null)
		{
			return ReferenceSingleton<RunModifiersManager>.Instance.DiceShortageRunModifier.GetBattleModifiedRewards(rewards);
		}
		return rewards;
	}
}
